FRAMEWORKS = {
    "soc2": ["access_control", "change_management", "monitoring"],
    "iso27001": ["access_control", "risk_assessment", "asset_inventory"],
    "gdpr": ["data_mapping", "consent_management", "breach_notification"],
}

IMPLEMENTED = {"access_control", "monitoring", "risk_assessment", "data_mapping", "breach_notification", "change_management"}

ORDER = ["soc2", "iso27001", "gdpr"]

def gaps(framework):
    return sorted(c for c in FRAMEWORKS[framework] if c not in IMPLEMENTED)

covered = 0
for fw in ORDER:
    g = gaps(fw)
    if g:
        print(f"{fw}: GAPS {','.join(g)}")
    else:
        print(f"{fw}: COMPLIANT")
        covered += 1

print(f"Frameworks fully covered: {covered}/{len(ORDER)}")
